package com.medicore.order.service; import com.medicore.order.client.InventoryClient; import com.medicore.order.dto.*; import com.medicore.order.entity.*; import com.medicore.order.repository.OrderRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class OrderService {private final OrderRepository repository; private final InventoryClient inventory; public OrderService(OrderRepository repository,InventoryClient inventory){this.repository=repository;this.inventory=inventory;} public OrderResponse create(OrderRequest r){List<OrderItem> reserved=new ArrayList<>();try{for(OrderItemRequest item:r.items()){inventory.reserve(item.medicineId(),new InventoryReservationRequest(item.quantity()));reserved.add(new OrderItem(item.medicineId(),item.quantity()));}return response(repository.save(new Order(r.userId(),reserved)));}catch(RuntimeException failure){reserved.forEach(item->{try{inventory.release(item.getMedicineId(),new InventoryReservationRequest(item.getQuantity()));}catch(RuntimeException ignored){}});throw new IllegalStateException("Unable to create order because inventory reservation failed",failure);}} public OrderResponse find(Long id){return response(repository.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found")));} private OrderResponse response(Order o){return new OrderResponse(o.getId(),o.getUserId(),o.getItems().stream().map(i->new OrderItemRequest(i.getMedicineId(),i.getQuantity())).toList(),o.getStatus());}}
